package com.xyz.question_bank_management_system.modules.learning.service.impl;
import com.xyz.question_bank_management_system.modules.agent.entity.ResourceBundle;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import com.xyz.question_bank_management_system.config.CorrelationContext;import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.agent.entity.*;import com.xyz.question_bank_management_system.modules.agent.mapper.PersonalizedResourceMapper;import com.xyz.question_bank_management_system.modules.agent.service.ResourceGenerationWorkflow;import com.xyz.question_bank_management_system.modules.course.service.PathRefreshApplicationService;import com.xyz.question_bank_management_system.modules.learning.dto.ResourceInteractionSubmitRequest;import com.xyz.question_bank_management_system.modules.learning.entity.*;import com.xyz.question_bank_management_system.modules.learning.mapper.LearningPathV1Mapper;import com.xyz.question_bank_management_system.modules.learning.service.*;import com.xyz.question_bank_management_system.modules.profile.entity.StudentProfileSnapshot;import com.xyz.question_bank_management_system.modules.profile.model.ValidatedInteraction;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;import java.math.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class InteractionSubmissionServiceImpl implements InteractionSubmissionService {private final PersonalizedResourceMapper mapper;private final LearningPathV1Mapper pathMapper;private final ProfileEvidenceConsumer profileConsumer;private final PathRefreshApplicationService pathService;private final ResourceGenerationWorkflow resourceWorkflow;private final ObjectMapper objectMapper;
 @Override @Transactional public Map<String,Object> submit(Long userId,String requestId,ResourceInteractionSubmitRequest request){if(!StringUtils.hasText(requestId))throw BizException.of(ErrorCode.PARAM_ERROR,"Idempotency-Key 不能为空");ResourceInteraction duplicate=mapper.selectInteractionByRequest(requestId);if(duplicate!=null){if(!Objects.equals(duplicate.getUserId(),userId))throw BizException.of(ErrorCode.CONFLICT,"幂等键已被其他请求使用");return view(duplicate,null,"REUSE");}if(request==null||!StringUtils.hasText(request.getGeneratedQuestionCode()))throw BizException.of(ErrorCode.PARAM_ERROR,"generatedQuestionCode 不能为空");ResourceItem item=mapper.selectQuestionForUpdate(request.getGeneratedQuestionCode());if(item==null||item.getGeneratedQuestionCode()==null)throw BizException.of(ErrorCode.NOT_FOUND,"生成题不存在");ResourceBundle bundle=mapper.selectBundleByIdForUpdate(item.getBundleId());if(bundle==null||!"PUBLISHED".equals(bundle.getStatus())||!Objects.equals(bundle.getUserId(),userId))throw BizException.of(ErrorCode.FORBIDDEN,"只有归属当前学生的 PUBLISHED 资源可提交");ResourceAssessmentRelease release=null;if("HIDDEN_UNTIL_ASSESSMENT".equals(item.getVisibility())){release=mapper.selectActiveRelease(userId,item.getId());if(release==null)throw BizException.of(ErrorCode.FORBIDDEN,"隐藏检测题尚未释放或已过期");}if(!Set.of("LEARNING_PRACTICE","KNOWLEDGE_ASSESSMENT").contains(item.getPurpose()))throw BizException.of(ErrorCode.PARAM_ERROR,"该资源项不是生成习题");ResourceUnit unit=mapper.selectUnitById(bundle.getResourceUnitId());LearningPath path=pathMapper.selectPathById(unit.getPathId());LearningPathProgress progress=pathMapper.selectProgressForUpdate(path.getId());long seq=Objects.requireNonNullElse(progress.getLastProcessedInteractionSeq(),0L)+1;Grade grade=grade(item.getGradingKeyJson(),request.getAnswer());List<Map<String,Object>> links=mapper.itemKnowledge(item.getId());Map<Long,BigDecimal> weights=new LinkedHashMap<>();Long primary=null;for(Map<String,Object> row:links){Long kp=number(row,"knowledge_point_id","knowledgePointId");BigDecimal w=decimal(row,"coverage_weight","coverageWeight");weights.put(kp,w);Object flag=value(row,"is_primary","isPrimary");if(flag!=null&&Integer.parseInt(String.valueOf(flag))==1)primary=kp;}if(weights.isEmpty())throw BizException.of(ErrorCode.EVIDENCE_INSUFFICIENT,"生成题缺少冻结知识点权重");try{ResourceInteraction i=new ResourceInteraction();i.setInteractionCode("int_"+UUID.randomUUID().toString().replace("-",""));i.setInteractionSeq(seq);i.setUserId(userId);i.setCourseId(bundle.getCourseId());i.setResourceBundleId(bundle.getId());i.setResourceVersion(bundle.getVersion());i.setResourceUnitId(unit.getId());i.setResourceItemId(item.getId());i.setGeneratedQuestionCode(item.getGeneratedQuestionCode());i.setQuestionPurpose(item.getPurpose());i.setVisibility(item.getVisibility());i.setQuestionDifficulty(item.getQuestionDifficulty());i.setPrimaryKnowledgePointId(primary);i.setKnowledgePointWeightsJson(objectMapper.writeValueAsString(weights));i.setScoreNormalized(grade.score());i.setCorrect(grade.correct()?1:0);i.setStatus("SUBMITTED");i.setActionOrigin(normalizeOrigin(request.getActionOrigin()));i.setGradingVersion("grading_v1");i.setAnswerJson(objectMapper.writeValueAsString(request.getAnswer()));i.setRequestId(requestId);i.setCorrelationId(CorrelationContext.get());i.setClientOccurredAt(request.getClientOccurredAt()==null?null:request.getClientOccurredAt().atZoneSameInstant(ZoneId.systemDefault()).toLocalDateTime());mapper.insertInteraction(i);String eventId="evt_"+UUID.randomUUID().toString().replace("-","");OutboxEvent out=new OutboxEvent();out.setEventId(eventId);out.setAggregateType("RESOURCE_INTERACTION");out.setAggregateId(i.getId());out.setEventType("learning.interaction.submitted");out.setPayloadJson(objectMapper.writeValueAsString(Map.of("interactionId",i.getId(),"userId",userId,"courseId",bundle.getCourseId(),"interactionSeq",seq)));out.setStatus("PENDING");out.setCorrelationId(CorrelationContext.get());mapper.insertOutbox(out);ValidatedInteraction validated=new ValidatedInteraction();validated.setId(i.getId());validated.setInteractionSeq(seq);validated.setUserId(userId);validated.setCourseId(bundle.getCourseId());validated.setScoreNormalized(i.getScoreNormalized());validated.setQuestionDifficulty(i.getQuestionDifficulty());validated.setQuestionPurpose(i.getQuestionPurpose());validated.setGradingConfidence(BigDecimal.ONE);validated.setKnowledgeWeights(weights);StudentProfileSnapshot snapshot=profileConsumer.apply(eventId,validated);pathMapper.advanceProgress(path.getId(),seq,i.getId(),i.getCorrect());Map<String,Object> pathResult=pathService.evaluateEvent(path.getPathCode(),Map.of("type",grade.correct()?"ANSWER_CORRECT":"ANSWER_WRONG","knowledgePointId",primary==null?0:primary));String pathState=String.valueOf(pathResult.getOrDefault("result","NO_PATH_EVENT"));String event="ACTIVE_UNCHANGED".equals(pathState)||"NO_PATH_EVENT".equals(pathState)?"PROFILE_VALUE_ONLY":grade.correct()?"RESOURCE_COMPLETED":"CONSECUTIVE_WRONG";Map<String,Object> decision=resourceWorkflow.decide(event,true);String action=String.valueOf(decision.get("resourceAction"));mapper.insertResourceDecision(userId,bundle.getCourseId(),path.getId(),path.getCurrentVersion(),i.getId(),action,event,CorrelationContext.get());if(release!=null)mapper.consumeRelease(release.getId());return view(i,snapshot,action);}catch(BizException ex){throw ex;}catch(Exception ex){throw new IllegalStateException("交互提交失败",ex);}}
 @Override public Map<String,Object> result(Long userId,String code){ResourceInteraction i=mapper.selectInteraction(code,userId);if(i==null)throw BizException.of(ErrorCode.NOT_FOUND,"交互不存在");return view(i,null,null);}
 private Grade grade(String gradingJson,Object answer){if(!StringUtils.hasText(gradingJson))throw BizException.of(ErrorCode.EVIDENCE_INSUFFICIENT,"生成题缺少 grading key");try{JsonNode key=objectMapper.readTree(gradingJson);String expected=key.isTextual()?key.asText():key.path("standardAnswer").asText();String actual=answer instanceof String s?s:objectMapper.writeValueAsString(answer);boolean ok=normalize(expected).equals(normalize(actual));return new Grade(ok,ok?BigDecimal.ONE:BigDecimal.ZERO);}catch(Exception ex){throw BizException.of(ErrorCode.BIZ_ERROR,"生成题评分规则无效");}}
 private String normalize(String s){return Objects.toString(s,"").replaceAll("\\s+","").trim().toLowerCase(Locale.ROOT);}private String normalizeOrigin(String v){String x=Objects.toString(v,"USER_INITIATED").toUpperCase(Locale.ROOT);return Set.of("USER_INITIATED","SYSTEM_RECOMMENDED","SYSTEM_REQUIRED").contains(x)?x:"USER_INITIATED";}
 private Object value(Map<String,Object>m,String a,String b){return m.containsKey(a)?m.get(a):m.get(b);}private Long number(Map<String,Object>m,String a,String b){Object v=value(m,a,b);return v instanceof Number n?n.longValue():Long.valueOf(String.valueOf(v));}private BigDecimal decimal(Map<String,Object>m,String a,String b){Object v=value(m,a,b);return v instanceof BigDecimal d?d:new BigDecimal(String.valueOf(v));}
 private Map<String,Object> view(ResourceInteraction i,StudentProfileSnapshot s,String action){Map<String,Object>m=new LinkedHashMap<>();m.put("interactionCode",i.getInteractionCode());m.put("scoreNormalized",i.getScoreNormalized());m.put("correct",i.getCorrect()==1);m.put("status",i.getStatus());if(s!=null){m.put("profileVersion",s.getProfileVersion());m.put("masteryUpdated",true);}if(action!=null)m.put("resourceAction",action);return m;}private record Grade(boolean correct,BigDecimal score){}
}
